config.prompt:
Turn these notes into 10 to 20 flashcards. Reply with ONLY CSV that has the header question,answer and nothing else. Quote any field that contains a comma.

NOTES:
{{ $.text }}

config.source:
import csv
import io


def main(input_data):
    text = input_data["text"].strip()
    if text.startswith("```"):
        text = text.strip("`").split("\n", 1)[-1].rsplit("```", 1)[0]
    rows = list(csv.reader(io.StringIO(text.strip())))
    if not rows or [c.strip().lower() for c in rows[0]] != ["question", "answer"]:
        raise ValueError("Claude's reply was not the flashcard CSV it was asked for. Run again, or check the notes.")
    rows = rows[1:]
    seen, cards = set(), []
    for r in rows:
        if len(r) < 2 or not r[0].strip() or not r[1].strip():
            continue
        key = r[0].strip().lower()
        if key not in seen:
            seen.add(key)
            cards.append((r[0].strip(), ",".join(r[1:]).strip()))
    if not cards:
        raise ValueError("The reply had a header but no usable cards. Run again, or check the notes.")
    out = io.StringIO()
    w = csv.writer(out, lineterminator="\n")
    w.writerow(["question", "answer"])
    w.writerows(cards)
    return {"csv": out.getvalue(), "count": len(cards)}
